"""Real JEE Main questions — Mathematics Unit 1: Sets, Relations and Functions. Our own solutions; chk re-solves each one
by brute force — relations by listing every ordered pair and testing the properties, counting questions by
enumerating the actual functions, domains and ranges by scanning the real line, functional equations by solving
the linear system they give. Skipped: a relation-counting item whose key (5) disagrees with a full enumeration (6),
continuity / differentiability / integration items (later units) and items already used in Sequences and Series."""
import itertools, math
from fractions import Fraction as F
from common import new_registry, pick, near, verify
P, add = new_registry()
def props(X, R):
    refl = all((a, a) in R for a in X); sym = all((b, a) in R for (a, b) in R); tr = all((a, d) in R for (a, b) in R for (c, d) in R if b == c)
    return refl, sym, tr
def lmn(X, R): return len(R), sum(1 for a in X if (a, a) not in R), sum(1 for (a, b) in R if (b, a) not in R)
def grid(lo, hi, n=40001): return [lo + (hi - lo) * i / (n - 1) for i in range(n)]
def one_one(f, xs):
    v = [f(x) for x in xs]; d = [b - a for a, b in zip(v, v[1:])]; return all(x > 0 for x in d) or all(x < 0 for x in d)
def onto_R(f, lo=-1e4, hi=1e4):   # does a continuous f on R reach very large values of both signs?
    v = [f(x) for x in grid(lo, hi, 20001)]; return max(v) > 1e3 and min(v) < -1e3

