add(('2025', 'Apr', '2025-04-02', 2), 'dom', 'If the domain of the function f(x) = \\f{1}{√{10 + 3x − x^{2}}} + \\f{1}{√{x + |x|}} is (a, b), then (1 + a)^{2} + b^{2} is equal to:', ['30', '26', '29', '25'], 2,
    lambda: (lambda xs: (lambda a, b: pick([30, 26, 29, 25], round((1 + a) ** 2 + b ** 2)))(min(xs), max(xs)))([x for x in grid(-10, 10, 200001) if 10 + 3 * x - x * x > 0 and x + abs(x) > 0]), ['10 + 3x − x^{2} > 0 → −2 < x < 5; x + |x| > 0 → x > 0.', 'Domain (0, 5): (1 + 0)^{2} + 5^{2} = 26.'], 'dom', 1)
